{% import "costeo_yelke/templates/print/oc_yelke.html" as oc %}
{#- Orden de compra de Yelke -- compra normal (materia prima, insumos, gastos).

    Las OC de SUBCONTRATACIÓN no usan este formato: llevan un renglón por pieza
    y la mayoría en $0, así que se imprimen con "Orden de Maquila", que los
    reagrupa. El formato correcto se elige solo (get_default_print_format). -#}
{{ oc.estilos() }}
<div class="pdf-container">

{{ oc.encabezado(doc) }}

<table class="table items-table">
    <thead>
        <tr>
            <th class="text-center" width="5%">#</th>
            <th class="text-center" width="10%">Img</th>
            <th width="35%">Artículo</th>
            <th class="text-right" width="8%">Cant.</th>
            <th class="text-right" width="8%">UOM</th>
            <th class="text-right" width="10%">Descuento</th>
            <th class="text-right" width="12%">P. Unitario</th>
            <th class="text-right" width="12%">Importe</th>
        </tr>
    </thead>
    <tbody>
        {% for row in doc.items %}
        <tr>
            <td class="text-center">{{ row.idx }}</td>
            <td class="text-center item-image-cell">
                {% if row.image %}
                    <img src="{{ row.image }}" alt="Img" class="item-image" />
                {% else %}
                    -
                {% endif %}
            </td>
            <td>
                <strong class="item-title">{{ row.item_name or row.item_code }}</strong>

                {% if row.item_code %}
                    <div class="item-code"><strong>Código:</strong> {{ row.item_code }}</div>
                {% endif %}

                {% if row.get("mx_product_service_key") %}
                    <div class="item-fiscal-code"><strong>Clave SAT:</strong> {{ row.mx_product_service_key }}</div>
                {% endif %}

                {% if row.description and row.description != row.item_name %}
                    <div class="item-description">{{ row.description }}</div>
                {% endif %}
            </td>
            <td class="text-right">{{ row.get_formatted("qty", doc) or row.qty }}</td>
            <td class="text-center">{{ row.uom or row.stock_uom or "Nos." }}</td>
            <td class="text-right">
                {% if row.discount_percentage %}{{ row.discount_percentage }}%{% else %}-{% endif %}
            </td>
            <td class="text-right">
                {{ row.get_formatted("rate", doc) or frappe.utils.fmt_money(row.rate, currency=doc.currency) }}
            </td>
            <td class="text-right">
                <strong>{{ row.get_formatted("amount", doc) or frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</strong>
            </td>
        </tr>
        {% endfor %}
    </tbody>
</table>

{{ oc.totales(doc) }}
{{ oc.cierre(doc) }}

</div>
